import { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import api from '../api/api';

export default function Payment() {
  const { id } = useParams(); // booking id
  const navigate = useNavigate();
  const [processing, setProcessing] = useState(false);
  const [error, setError] = useState('');

  const handlePay = async () => {
    setProcessing(true);
    setError('');
    try {
      // Step 1: ask our backend to create a Razorpay order for this booking's amount
      const { data: order } = await api.post('/payments/create-order', { bookingId: id });

      // Step 2: open Razorpay's checkout popup (test mode - use their test card/UPI details)
      const options = {
        key: order.keyId,
        amount: order.amount,
        currency: order.currency,
        name: 'Smart EV Charging',
        description: 'Charging slot booking',
        order_id: order.orderId,
        handler: async (response) => {
          // Step 3: send the payment result back to our backend to verify + confirm booking
          try {
            await api.post('/payments/verify', {
              bookingId: id,
              razorpay_order_id: response.razorpay_order_id,
              razorpay_payment_id: response.razorpay_payment_id,
              razorpay_signature: response.razorpay_signature,
            });
            navigate(`/confirmation/${id}`);
          } catch (err) {
            setError('Payment verification failed. Please contact support.');
            setProcessing(false);
          }
        },
        modal: {
          ondismiss: () => setProcessing(false), // user closed the popup without paying
        },
        theme: { color: '#0f6e56' },
      };

      const razorpayCheckout = new window.Razorpay(options);
      razorpayCheckout.open();
    } catch (err) {
      setError(err.response?.data?.message || 'Could not start payment');
      setProcessing(false);
    }
  };

  return (
    <div className="payment-page">
      <h2>Complete your payment</h2>
      <p>You're one step away from reserving your charging slot.</p>
      {error && <p className="error">{error}</p>}
      <button onClick={handlePay} disabled={processing}>
        {processing ? 'Opening checkout...' : 'Pay now'}
      </button>
      <p className="hint">Test mode: use card 4111 1111 1111 1111, any future expiry, any CVV.</p>
    </div>
  );
}
